## 三、字段写入与异常分支伪代码

### 3.1 前端查询与确认伪代码

```typescript
// 状态
let currentRequestId = 0;
let candidates: CandidateSummary[] = [];
let selectedCandidateId: string | null = null;

// 进入编辑状态或身份键变化时调用
async function onIdentityChanged(name: string, idNumber: string, region: string) {
  currentRequestId++;
  const requestId = currentRequestId;

  if (!name || !idNumber) {
    candidates = [];
    selectedCandidateId = null;
    showMessage("请先填写姓名和证件号");
    return;
  }

  try {
    const result = await queryCandidates({ name, idNumber, region });
    if (requestId !== currentRequestId) {
      return; // 迟到旧请求，丢弃
    }
    candidates = sortCandidates(result);
    if (candidates.length === 0) {
      showMessage("未找到匹配记录");
      return;
    }
    showConfirmDialog(candidates); // 仅展示编号、地区、更新时间、姓名掩码
  } catch (e) {
    if (requestId !== currentRequestId) return;
    showMessage("查询失败，本次未执行补值，原数据保留");
  }
}

// 用户确认候选
async function onConfirmCandidate(candidateId: string, region: string) {
  const requestId = currentRequestId;
  try {
    const detail = await getCandidateDetail(candidateId);
    if (requestId !== currentRequestId) return;

    if (detail.id !== candidateId) {
      showMessage("候选信息不一致，已停止补值");
      return;
    }

    if (!detail.region || detail.region !== region) {
      showMessage("该候选地区信息缺失或无法核验，已停止补值");
      return;
    }

    applyFields(detail);
  } catch (e) {
    if (requestId !== currentRequestId) return;
    showMessage("获取详情失败，本次未执行补值，原数据保留");
  }
}

// 字段写入
function applyFields(detail: CandidateDetail) {
  const form = getCurrentForm();

  if (isEmpty(form.phone) && !isEmpty(detail.phone)) {
    form.phone = detail.phone;
  }
  if (isEmpty(form.occupation) && !isEmpty(detail.occupation)) {
    form.occupation = detail.occupation;
  }
  if (isEmpty(form.address) && !isEmpty(detail.address)) {
    form.address = detail.address;
  }
}

function isEmpty(value: unknown): boolean {
  return value === null || value === undefined || value === "";
}

// 用户取消
function onCancel() {
  selectedCandidateId = null;
  closeDialog();
  // 不修改任何表单字段
}
```

### 3.2 后端补值服务伪代码

```java
public class BaselineFillService {

    public List<CandidateSummary> queryCandidates(String name, String idNumber, String region) {
        if (name == null || name.isBlank() || idNumber == null || idNumber.isBlank()) {
            return List.of();
        }
        List<BaselineRecord> records = baselineMapper.selectByNameAndId(name, idNumber);
        return records.stream()
            .filter(r -> region != null && region.equals(r.getRegion()))
            .sorted(Comparator.comparing(BaselineRecord::getUpdatedAt).reversed()
                .thenComparing(BaselineRecord::getRecordNo))
            .map(this::toSummary)
            .toList();
    }

    public CandidateDetail getDetail(String candidateId, String region) {
        BaselineRecord record = baselineMapper.selectById(candidateId);
        if (record == null) {
            throw new BusinessException("CANDIDATE_NOT_FOUND");
        }
        if (record.getRegion() == null || !record.getRegion().equals(region)) {
            throw new BusinessException("REGION_UNVERIFIABLE");
        }
        return toDetail(record);
    }

    public void applyFields(FormTarget target, CandidateDetail detail) {
        if (isEmpty(target.getPhone()) && !isEmpty(detail.getPhone())) {
            target.setPhone(detail.getPhone());
        }
        if (isEmpty(target.getOccupation()) && !isEmpty(detail.getOccupation())) {
            target.setOccupation(detail.getOccupation());
        }
        if (isEmpty(target.getAddress()) && !isEmpty(detail.getAddress())) {
            target.setAddress(detail.getAddress());
        }
    }

    private boolean isEmpty(Object value) {
        return value == null || (value instanceof String s && s.isEmpty());
    }
}
```

### 3.3 异常分支汇总

| 分支 | 处理 |
|------|------|
| 姓名或证件号为空 | 不查询，提示补全身份键 |
| 查询无候选 | 不弹确认框，提示未找到匹配记录 |
| 查询失败 | 保留原值，提示查询失败，不伪装为无匹配 |
| 地区缺失或无法核验 | 不视为匹配成功，停止写入并提示 |
| 地区明确不符 | 不展示为可补值候选 |
| 详情编号与确认编号不一致 | 停止写入，提示信息不一致 |
| 详情失败 | 保留原值，提示获取详情失败 |
| 用户取消/关闭/离开 | 不写入，保持原值和未保存编辑值 |
| 迟到旧请求 | 丢弃，不更新候选列表 |
| 目标值非空 | 不覆盖，保留原值 |
| 目标值为 0/false | 视为有效原值，不覆盖 |
| 目标值为 null/空字符串且来源有值 | 补入来源值 |
| 目标值为空且来源也为空 | 保持空值，不制造占位 |

